const people=[{id:1,name:'Andreas',role:'Grandma’s father',x:420,y:95,parents:[],partner:2},{id:2,name:'Eleni',role:'Grandma’s mother',x:580,y:95,parents:[],partner:1},{id:3,name:'Sofia',role:'Grandma’s sister',x:290,y:285,parents:[1,2]},{id:4,name:'Maria',role:'Grandma',x:500,y:285,parents:[1,2],partner:5},{id:5,name:'Nikos',role:'Grandpa',x:680,y:285,parents:[],partner:4},{id:6,name:'Costas',role:'Grandma’s brother',x:880,y:285,parents:[1,2]},{id:7,name:'Anna',role:'Grandma’s daughter',x:420,y:475,parents:[4,5]},{id:8,name:'Petros',role:'Grandma’s son',x:700,y:475,parents:[4,5]},{id:9,name:'Irene',role:'Grandma’s sister',x:40,y:285,parents:[1,2]}];
const nodes=document.querySelector('#nodes'),tree=document.querySelector('#tree'),view=document.querySelector('#viewport');
tree.querySelector('path').setAttribute('d','M420 95H580 M500 95V185 M100 185H880 M100 185V232 M290 185V232 M500 185V232 M880 185V232 M500 285H680 M590 285V375 M420 375H700 M420 375V422 M700 375V422');people[8].x=100;
people.forEach(p=>{const b=document.createElement('button');b.className='person'+(p.id===4?' grandma':'');b.style.left=p.x+'px';b.style.top=p.y+'px';b.dataset.id=p.id;b.innerHTML=`<span class="initials">${p.name[0]}</span><strong>${p.name}</strong><small>${p.role}</small>`;b.onclick=()=>show(p);nodes.append(b)});
function names(ids){return ids.map(id=>people.find(p=>p.id===id).name).join(', ')||'Not recorded'}
function show(p){const children=people.filter(c=>c.parents.includes(p.id));document.querySelector('#details').innerHTML=`<h2>${p.name}</h2><p>${p.role}</p><div class="relation"><span>Parents</span>${names(p.parents)}</div><div class="relation"><span>Partner</span>${p.partner?names([p.partner]):'Not recorded'}</div><div class="relation"><span>Children</span>${children.length?children.map(c=>c.name).join(', '):'Not recorded'}</div><p>This is a fictional sample profile. Later, we can add your relative’s photo, village, dates, and memories.</p>`;document.querySelector('#profile').showModal()}
document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelector('#install').onclick=()=>document.querySelector('#help').showModal();document.querySelector('#search').oninput=e=>{const q=e.target.value.toLowerCase().trim();let found=0;document.querySelectorAll('.person').forEach(b=>{const p=people.find(p=>p.id==b.dataset.id);const match=(p.name+' '+p.role).toLowerCase().includes(q);b.classList.toggle('dim',!!q&&!match);b.classList.toggle('match',!!q&&match);if(match)found++});document.querySelector('#count').textContent=q?`${found} matching relatives`:'9 relatives · 3 generations'};
let zoom=1;function scale(z){zoom=Math.max(.6,Math.min(1.5,z));tree.style.zoom=zoom}document.querySelector('#more').onclick=()=>scale(zoom+.15);document.querySelector('#less').onclick=()=>scale(zoom-.15);document.querySelector('#reset').onclick=()=>{scale(1);view.scrollLeft=(1000-view.clientWidth)/2};view.scrollLeft=(1000-view.clientWidth)/2;
